<template><div class="page"><div class="head"><div><h2>巡检数据大屏</h2><p>本月任务完成、逾期与问题整改的总体情况。</p></div><el-button @click="load">刷新</el-button></div><div class="stats"><div v-for="x in cards" :key="x.label" class="stat"><span>{{x.label}}</span><b :class="x.cls">{{x.value||0}}</b></div></div><div class="grid"><div class="panel"><h3>各类巡检完成情况</h3><el-table :data="data.typeStats"><el-table-column prop="typeName" label="巡检类型"/><el-table-column prop="total" label="任务数"/><el-table-column prop="completed" label="已完成"/><el-table-column prop="overdue" label="逾期"/><el-table-column label="完成率"><template #default="s"><el-progress :percentage="s.row.total?Math.round(s.row.completed*100/s.row.total):0"/></template></el-table-column></el-table></div><div class="panel"><h3>近 14 日完成趋势</h3><div v-for="x in data.recent||[]" :key="x.day" class="trend"><span>{{String(x.day).slice(0,10)}}</span><el-progress :percentage="x.total?Math.round(x.completed*100/x.total):0" :format="()=>`${x.completed}/${x.total}`"/></div><el-empty v-if="!data.recent?.length" description="暂无趋势数据"/></div></div></div></template>
<script setup lang="ts">import{ref,computed,onMounted}from'vue';import{inspectionApi}from'@/api/inspection';const data=ref<any>({summary:{},typeStats:[],recent:[]});const unwrap=(r:any)=>r?.data?.data??r?.data??r;const cards=computed(()=>[{label:'本月任务',value:data.value.summary?.total},{label:'待巡检',value:data.value.summary?.pending},{label:'已完成',value:data.value.summary?.completed,cls:'ok'},{label:'已逾期',value:data.value.summary?.overdue,cls:'bad'},{label:'待整改',value:data.value.summary?.rectification,cls:'warn'},{label:'未闭环问题',value:data.value.openIssues,cls:'warn'}]);async function load(){data.value=unwrap(await inspectionApi.dashboard())}onMounted(load)
</script><style scoped>.page{padding:20px}.head{display:flex;justify-content:space-between}.head h2{margin:0}.head p{color:#777}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.stat,.panel{background:#fff;border-radius:9px;padding:18px}.stat span{display:block;color:#777}.stat b{font-size:30px;line-height:1.6}.ok{color:#2e9b62}.bad{color:#f56c6c}.warn{color:#e6a23c}.grid{display:grid;grid-template-columns:1.3fr 1fr;gap:12px;margin-top:12px}.trend{display:grid;grid-template-columns:100px 1fr;align-items:center;margin:13px 0}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.page{padding:10px}}</style>
